// Customizable Variables

var V_NAME = "Example Signal";     // Value name displayed in the display 
var V_MIN = 0;             // generated value minimum
var V_MAX = 1000;              // generated value maximum
var V_STEPS_PER_PERIOD = 21; // > 1.
var V_TICKS_PER_STEP = 3;    // > 1. 
var V_TICK_DELAY = 150;       // delay inside the the loop() function before the next iteration 
var V_CURVE_TYPE = "triangle";   // type of the curve the values will follow
var V_CURVE_PARAM = 0.25;     // curve parameter is from 0 to 1
var V_OUT_D = [0, 1, 2, 3, 4, 5];   // output signal value into digital outputs designated by their indices
var V_OUT_A = [0, 1, 2, 3];   // output signal value into analog outputs designated by their indices

// Implementation 

var tick = 0;
var step_tick = 0;
var display_sep = "\n             ";
var oo_ticks_period = 1.0 / (V_STEPS_PER_PERIOD * V_TICKS_PER_STEP);
var signal_func = null;
var EPS = 1.0e-6; 
var OFF_0 = EPS;
var OFF_1 = 1.0 - EPS;
var OO_VCP = 1.0 / V_CURVE_PARAM;
var OO_1mVCP = 1.0 / (1.0 - V_CURVE_PARAM);
var PI2 = Math.PI * 2.0;
var uiControl;

function reset(){
	tick = 0;
	step_tick = 0;
	oo_ticks_period = 1.0 / (V_STEPS_PER_PERIOD * V_TICKS_PER_STEP);
	OO_VCP = 1.0 / V_CURVE_PARAM;
	OO_1mVCP = 1.0 / (1.0 - V_CURVE_PARAM);
}

function setup() {
    setup_signal_func();

    if(V_CURVE_PARAM < 0 || V_CURVE_PARAM > 1)
    	throw("ERROR: V_CURVE_PARAM must be from range [0.0, 1.0]: \"" + V_CURVE_PARAM + "\"");

    var i, len;
    for(i=0, len=V_OUT_D.length; i<len; ++i)
        if(!check_bounds(V_OUT_D[i], 0, 5))
       		throw("ERROR: V_OUT_D index must be from 0-5: \"" + V_OUT_D[i] + "\"");

    for(i=0, len=V_OUT_A.length; i<len; ++i)
        if(!check_bounds(V_OUT_A[i], 0, 3))
       		throw("ERROR: V_OUT_A index must be from 0-3: \"" + V_OUT_A[i] + "\"");


    output(signal_func(tick * oo_ticks_period));
    step_tick = 0;

    uiControl = new UiControl();
}

function loop() {
    ++tick;
    ++step_tick;
//    Serial.println(step_tick);
//    Serial.println(V_TICKS_PER_STEP);
    if(step_tick == V_TICKS_PER_STEP){
        var time = tick * oo_ticks_period,
            func_value = signal_func(time);
//	Serial.println(func_value);
        output(func_value);
        step_tick = 0;
    }
    delay(V_TICK_DELAY);
    delay(0);
}

function setup_signal_func(){
    switch(V_CURVE_TYPE) {
        case 'cosine': signal_func = signal_cosine; break;
        case 'cosine_inv': signal_func = signal_cosine_inv; break;
        case 'square': signal_func = signal_square; break;
        case 'square_inv': signal_func = signal_square_inv; break;
        case 'triangle': signal_func = signal_triangle; break;
        case 'triangle_inv': signal_func = signal_triangle_inv; break;
        case 'zero': signal_func = signal_zero; break;
        case 'one': signal_func = signal_one; break;
        default: throw("ERROR: Unknown signal curve type: \"" + V_CURVE_TYPE + "\"");
    }
}

function output(func_value){
    var disp_value = Math.floor(V_MIN + func_value * (V_MAX - V_MIN));
    var i,len;

    update_display(V_NAME, disp_value);

    // analog output values are from 0 to 255 inclusive 
    var avalue = Math.floor(func_value * 255);

    for(i=0, len=V_OUT_D.length; i<len; ++i)
        analogWrite(V_OUT_D[i], avalue);

    for(i=0, len=V_OUT_A.length; i<len; ++i)
        analogWrite(V_OUT_A[i]+A0, avalue);
}

function check_bounds(v, min, max){
	return v >= min && v <= max;
}

function update_display(name, value){
    var text = name + display_sep + value;    
    setCustomText(20,15,150,100, text);
}

// signal functions 

function signal_triangle(time){
    var t = time - Math.floor(time),
        EPS = 1e-6;
    if(V_CURVE_PARAM < OFF_0)
        return 1.0 - t;
    else if(V_CURVE_PARAM > OFF_1)
        return t;
    else if(t <= V_CURVE_PARAM)
        return t * OO_VCP;
    else if(t > V_CURVE_PARAM)
        return (1.0 - t) * OO_1mVCP;
}

function signal_triangle_inv(time){
    return 1.0 - signal_triangle(time);
}


function signal_cosine_inv(time){
    return 1.0 - signal_cosine(time);
}

function signal_cosine(time){
    return 0.5 * (1.0 + Math.cos(PI2*time));
}

function signal_square(time){
    var t = time - Math.floor(time);
    if(t < V_CURVE_PARAM)
        return 1;
    return 0;
}

function signal_square_inv(time){
    return 1.0 - signal_square(time);
}

function signal_zero(time){
    return 0; 
}

function signal_one(time){
    return 1; 
}

function UiControl() {
    this.ui = {
        type: "Signal Generator",
        states: [
            {
                name: "Signal Name", type: "options", controllable: true, vname: "V_NAME",
                options: {
                    name: V_NAME
                }
            }, {
                name: "Curve Shape", type: "options", controllable: true, vname: "V_CURVE_TYPE",
                options: {triangle:"Tri", triangle_inv:"TriInv", square:"Sqr", square_inv:"SqrInv", one: "Max", zero:"Min", cosine:"Cos", cosine_inv:"CosInv"}                
            }, {
                name: "Curve Parameter", type: "options", controllable: true, vname: "V_CURVE_PARAM",
                options: {}
            }, {
                name: "Min", type: "options", controllable: true, vname: "V_MIN",
                options: {}
            }, {
                name: "Max", type: "options", controllable: true, vname: "V_MAX",
                options: {}
            }, {
                name: "Tick Delay", type: "options",        controllable: true, vname: "V_TICK_DELAY",
                options:{}
            }, {
                name: "Sample Count", type: "options",      controllable: true, vname: "V_STEPS_PER_PERIOD",
                options:{}
            }, {
                name: "Ticks Per Sample", type: "options",          controllable: true, vname: "V_TICKS_PER_STEP",
                options:{}
            }
        ]
    };

    for(var d=0; d<6; ++d){
        this.ui.states.push({                                                           
            name: "Out D"+d, type: "bool", controllable: true, vname: "V_OUT_D"+d
        });
    }

    for(var a=0; a<4; ++a){
        this.ui.states.push({                                                           
            name: "Out D"+a, type: "bool", controllable: true, vname: "V_OUT_A"+a
        });
    }

    for(var s=0; s<this.ui.states.length; ++s){
        var state = this.ui.states[s];
        switch(state.vname){
            case "V_MAX": 
                for(var mx=-500; mx<=1050; mx+=84)
                    state.options[mx] = mx;
                break;
            case "V_MIN": 
                for(var m=-1000; m<=500; m+=100)
                    state.options[m] = m;
                break;
            case "V_TICK_DELAY": 
                for(var td=75; td<=1000; td+=75)
                    state.options[td] = td;
                break;
            case "V_STEPS_PER_PERIOD": 
                for(var spp=1; spp<=50; spp+=5)
                    state.options[spp] = spp;
                break;
            case "V_TICKS_PER_STEP": 
                for(var tps=1; tps<=20; tps+=2)
                    state.options[tps] = tps;
                break;
            case "V_CURVE_PARAM": 
                var params = [0,25,50,75,100];
                for(var p=0; p<params.length; ++p)
                    state.options[params[p]] = params[p]/100;
                break;
        }
    }

    IoEClient.setup(this.ui);

    var me = this;
	IoEClient.onInputReceive = function(uiData) {
        me.ui2vars(uiData);
	};

    this.vars2ui();
}    

UiControl.prototype.vars2ui = function() {
    var fileds = []; 
    for(var s=0; s<this.ui.states.length; ++s){
    	var vname = this.ui.states[s].vname;
        var state = this.var_value(vname);
        fileds.push(state);
    }
    var uiData = fileds.join(",");
    Serial.println("sending uiData: " + uiData);
    IoEClient.reportStates(uiData);
};

UiControl.prototype.ui2vars = function(uiData) {
    Serial.println("receiving uiData: " + uiData);
    var fields = uiData.split(',');
    for(var f=0; f<fields.length; ++f){
        var state = this.ui.states[f];
        if(state === undefined)
            throw "ERROR: Unknown ui state at index: "+f+"\n\tin data received: \n\t\t"+uiData;
        this.var_value(state.vname, fields[f]);
    }

	reset();

    this.vars2ui();
};

UiControl.prototype.var_value = function(vname, value) {
    switch(vname){
        case "V_NAME": 
            if(value === undefined)
                return 'name'; // option id
            break;
        case "V_MAX": 
            if(value !== undefined)
                V_MAX = parseInt(value); 
            else
                return V_MAX;
            break;
        case "V_MIN": 
            if(value !== undefined)
                V_MIN = parseInt(value); 
            else
                return V_MIN;
            break;
        case "V_CURVE_PARAM": 
            if(value !== undefined)
                V_CURVE_PARAM = parseFloat(value)/100; 
            else{
                return V_CURVE_PARAM*100;
            }
            break;
        case "V_CURVE_TYPE": 
            if(value !== undefined){
                V_CURVE_TYPE = value; 
                setup_signal_func();
            }
            else
                return V_CURVE_TYPE;
            break;
        case "V_TICK_DELAY": 
            if(value !== undefined)
                V_TICK_DELAY = parseFloat(value); 
            else
                return V_TICK_DELAY;
            break;
        case "V_STEPS_PER_PERIOD": 
            if(value !== undefined)
                V_STEPS_PER_PERIOD = parseInt(value); 
            else
                return V_STEPS_PER_PERIOD;
            break;
        case "V_TICKS_PER_STEP":
            if(value !== undefined)
                V_TICKS_PER_STEP = parseInt(value); 
            else
                return V_TICKS_PER_STEP;
            break;
        default:
        	var result = this.var_value_da_out(vname, value, V_OUT_D, "V_OUT_D");
            if(result === undefined)
            	result = this.var_value_da_out(vname, value, V_OUT_A, "V_OUT_A");
            return result;
    }
};

/*
UiControl.prototype.var_value_num = function(vname, value, value_convert) {
	var ev = eval;
    if(value !== undefined)
        ev(vname + "=" + value_convert(value)); 
    else
        return ev(vname);
};
*/

UiControl.prototype.var_value_da_out = function(vname, value, out_arr, out_var_name) {
    if(vname.substr(0,7) === out_var_name){
        var index = parseInt(vname.substr(7,1));
        if(value !== undefined){
    		Serial.println(vname + " (setting): " + value);
            if(value == 1){
                if(out_arr.indexOf(index) == -1)
                    out_arr.push(index);
            }
            else {
                var out = [];
                while(out_arr.length > 0){
                    var di = out_arr.pop();
                    if(di != index)
                        out.push(di);
                }
                while(out.length > 0)
                    out_arr.push(out.pop());
            }
        }
        else{
            return out_arr.indexOf(index) == -1 ? 0 : 1;
        }
        return index;
    }
};

from time import *
import math
from physical import *
from gpio import *


# Customizable Variables

V_NAME = "Example Signal" # Value name displayed in the display        # var V_NAME
V_MIN = 0 # generated value minimum        # var V_MIN
V_MAX = 1000 # generated value maximum        # var V_MAX
V_STEPS_PER_PERIOD = 21 # > 1.        # var V_STEPS_PER_PERIOD
V_TICKS_PER_STEP = 3 # > 1.        # var V_TICKS_PER_STEP
V_TICK_DELAY = 150 # delay inside the the loop() function before the next iteration        # var V_TICK_DELAY
V_CURVE_TYPE = "triangle" # type of the curve the values will follow        # var V_CURVE_TYPE
V_CURVE_PARAM = 0.25 # curve parameter is from 0 to 1        # var V_CURVE_PARAM
V_OUT_D = [0, 1, 2, 3, 4, 5] # output signal value into digital outputs designated by their indices        # var V_OUT_D
V_OUT_A = [0, 1, 2, 3] # output signal value into analog outputs designated by their indices        # var V_OUT_A

# Implementation

tick = 0        # var tick
step_tick = 0        # var step_tick
display_sep = "\n             "        # var display_sep
oo_ticks_period = 1.0 / (V_STEPS_PER_PERIOD * V_TICKS_PER_STEP)        # var oo_ticks_period
signal_func = None        # var signal_func
EPS = 1.0e-6        # var EPS
OFF_0 = EPS        # var OFF_0
OFF_1 = 1.0 - EPS        # var OFF_1
OO_VCP = 1.0 / V_CURVE_PARAM        # var OO_VCP
OO_1mVCP = 1.0 / (1.0 - V_CURVE_PARAM)        # var OO_1mVCP
PI2 = math.pi * 2.0        # var PI2
uiControl = None        # var uiControl


def setup ():
    global step_tick
    setup_signal_func()

    if V_CURVE_PARAM < 0 or V_CURVE_PARAM > 1:
        raise ("ERROR: V_CURVE_PARAM must be from range [0.0, 1.0]: \"" + V_CURVE_PARAM + "\"")

    for i in xrange( 0, len(V_OUT_D)):
        if not check_bounds(V_OUT_D[i], 0, 5):
            raise ("ERROR: V_OUT_D index must be from 0-5: \"" + V_OUT_D[i] + "\"")

    for i in xrange( 0, len(V_OUT_A)):
        if not check_bounds(V_OUT_A[i], 0, 3):
            raise ("ERROR: V_OUT_A index must be from 0-3: \"" + V_OUT_A[i] + "\"")

    output(signal_func(tick * oo_ticks_period))
    step_tick = 0

    #uiControl = new UiControl()

def loop ():
    global tick, step_tick
    tick += 1
    step_tick += 1
    if step_tick == V_TICKS_PER_STEP:
        time = tick * oo_ticks_period        # var time
        func_value = signal_func(time)
        output(func_value)
        step_tick = 0

    delay(V_TICK_DELAY)



def setup_signal_func ():
    global signal_func
    if V_CURVE_TYPE is 'cosine':
        signal_func = signal_cosine
    elif V_CURVE_TYPE is 'cosine_inv':
        signal_func = signal_cosine_inv
    elif V_CURVE_TYPE is 'square':
        signal_func = signal_square
    elif V_CURVE_TYPE is 'square_inv':
        signal_func = signal_square_inv
    elif V_CURVE_TYPE is 'triangle':
        signal_func = signal_triangle
    elif V_CURVE_TYPE is 'triangle_inv':
        signal_func = signal_triangle_inv
    elif V_CURVE_TYPE is 'zero':
        signal_func = signal_zero
    elif V_CURVE_TYPE is 'one':
        signal_func = signal_one
    else:
        raise ("ERROR: Unknown signal curve type: \"" + V_CURVE_TYPE + "\"")




def output (func_value) :
    disp_value = math.floor(V_MIN + func_value * (V_MAX - V_MIN))        # var disp_value

    update_display(V_NAME, disp_value)

    # analog output values are from 0 to 255 inclusive
    avalue = math.floor(func_value * 255)        # var avalue

    for i in xrange( 0, len(V_OUT_D)):
        analogWrite(V_OUT_D[i], avalue)

    for i in xrange( 0, len(V_OUT_A)):
        analogWrite(V_OUT_A[i] + A0, avalue)



def check_bounds (v, min, max) :
    return min <= v <= max



def update_display (name, value) :
    text = name + display_sep + str(value)        # var text
    setCustomText(20, 15, 150, 100, text)


# signal functions


def signal_triangle (time) :
    t = time - math.floor(time)        # var t
    if V_CURVE_PARAM < OFF_0:
        return 1.0 - t
    elif V_CURVE_PARAM > OFF_1:
        return t
    elif t <= V_CURVE_PARAM:
        return t * OO_VCP
    elif t > V_CURVE_PARAM:
        return (1.0 - t) * OO_1mVCP



def signal_triangle_inv (time):
    return 1.0 - signal_triangle(time)




def signal_cosine_inv (time):
    return 1.0 - signal_cosine(time)



def signal_cosine (time):
    return 0.5 * (1.0 + math.cos(PI2 * time))



def signal_square (time):
    t = time - math.floor(time)        # var t
    if t < V_CURVE_PARAM:
        return 1
    return 0



def signal_square_inv (time):
    return 1.0 - signal_square(time)



def signal_zero (time):
    return 0



def signal_one (time):
    return 1


if __name__ == "__main__":
    setup()
    while True:
        loop()
        sleep(0)
